-- Goddess of Nature change for multi-tile Natural Wonders
-----------------------------------------------------------
UPDATE Language_ko_KR SET Text = REPLACE(Text, '+2 [ICON_CULTURE]', '+3 [ICON_CULTURE]') WHERE Tag ='TXT_KEY_BELIEF_ONE_WITH_NATURE';
UPDATE Language_ko_KR SET Text = Text||' (다중 타일 자연 경관의 모든 타일 간에 비례적으로 분할됨)' WHERE Tag ='TXT_KEY_BELIEF_ONE_WITH_NATURE';
-----------------------------------------------------------
-- New and updated one-liners (Game Info in Civilopedia)
-----------------------------------------------------------
UPDATE Language_ko_KR SET Text = '그 물을 마시거나 목욕하는 사람의 젊음을 되찾아준다고 전해지는 신화 속의 샘입니다. 그러한 샘에 대한 이야기는 수천 년 동안 전 세계적으로 전해져 왔습니다. 이러한 많은 전설을 바탕으로 탐험가와 모험가들은 일반적으로 마법의 물과 관련된 이 찾기 힘든 장소나 노화에 대한 다른 치료법을 찾았습니다.' WHERE Tag = 'TXT_KEY_CIV5_FEATURES_FOUNTAIN_YOUTH_HELP';
UPDATE Language_ko_KR SET Text = '많은 전설에 따르면 왕들이 너무 부유해서 머리부터 발끝까지 금가루를 뒤집어썼다는 신화 속의 황금 도시입니다. 전설은 원주민 문화에서 영감을 얻었으며 더 발전된 문명의 정착민들 사이에 퍼졌습니다. 그 후 수십 년 동안 대륙 전역의 여러 곳에서 도시를 찾았습니다.' WHERE Tag = 'TXT_KEY_CIV5_FEATURES_EL_DORADO_HELP';
UPDATE Language_ko_KR SET Text = '세 개의 화산 원뿔로 구성된 세계에서 가장 높은 독립형 산인 거대한 휴화산입니다. 주요 하이킹 및 등반 목적지로 기술적으로 어렵지는 않지만 고산병의 심각한 위험을 초래합니다. 등반가는 열대에서 북극까지 다양한 기후대를 여행하며 정상 도달 성공률이 매우 낮습니다.' WHERE Tag = 'TXT_KEY_CIV5_FEATURES_KILIMANJARO_HELP';
UPDATE Language_ko_KR SET Text = '많은 전설에 따르면 성인의 발자국이 있는 신성한 산으로, 4대 종교 중 어느 종교가 언급하느냐에 따라 다릅니다. 산은 서로 다른 신앙 간의 화합의 상징으로 여겨집니다. 조명된 길과 등반가에게 도움을 제공하는 많은 쉼터가 있어 독특한 일반적인 순례지입니다.' WHERE Tag = 'TXT_KEY_CIV5_FEATURES_SRI_PADA_HELP';

INSERT INTO Language_ko_KR
			(Tag,											Text)
VALUES		('TXT_KEY_CIV5_FEATURES_CRATER_HELP',			'니켈-철 운석의 충돌로 형성된 세계에서 가장 큰 크레이터 중 하나입니다. 침식이 없어 크레이터의 모양이 보존되어 아폴로 우주비행사 훈련 및 수많은 다른 우주 임무에 사용될 수 있었습니다. 크레이터를 공공 랜드마크로 만들려는 시도에도 불구하고 배린저 가족이 개인적으로 소유하고 있습니다.'),
			('TXT_KEY_CIV5_FEATURES_FUJI_HELP',				'세 개의 지각판이 교차하는 지점에 위치한 활성 성층 화산으로 "3대 영산" 중 하나이자 뛰어난 경치를 자랑하는 명승지이자 사적지입니다. 유네스코에 따르면 "예술가와 시인에게 영감을 주었으며 수 세기 동안 순례지였습니다".'),
			('TXT_KEY_CIV5_FEATURES_MESA_HELP',				'세계에서 가장 큰 평정산으로서 풍경, 기후, 식생에서 극적인 대조를 제공합니다. 고원은 서쪽의 그랜드 밸리를 포함하여 많은 강 계곡을 둘러싸고 있습니다. 광활한 표면에는 식수와 관개용으로 사용되는 많은 저수지를 포함하여 수백 개의 흩어진 호수가 점재해 있습니다.'),
			('TXT_KEY_CIV5_FEATURES_NEW_REEF_HELP',			'수백 개의 개별 산호초와 섬으로 구성되어 있으며 수천 킬로미터에 걸쳐 뻗어 있는 세계 최대의 산호초 시스템입니다. 우주에서도 볼 수 있으며 살아있는 유기체로 만들어진 세계 최대의 단일 구조물입니다. 이 놀라운 동물 구조물은 취약하거나 멸종 위기에 처한 많은 종을 포함하여 놀라운 생명 다양성을 지원합니다.'),
			('TXT_KEY_CIV5_FEATURES_VOLCANO_HELP',			'기록된 역사상 가장 격렬한 일련의 강력한 폭발로 형성된 칼데라로 수천 명의 사람들을 죽였으며 여전히 활동 중입니다. 폭발 이듬해 북반구의 여름 기온이 크게 떨어졌고, 나중에 아낙 크라카타우 또는 "크라카토아의 아이"라는 새로운 섬이 칼데라에서 나타났습니다.'),
			('TXT_KEY_CIV5_FEATURES_GIBRALTAR_HELP',		'지중해 입구를 표시하는 거대한 석회암 산입니다. 요새 역할을 하며 미로 같은 인공 터널 네트워크를 포함하고 있으며 동시에 상부 구역은 수백 마리의 바바리원숭이가 서식하는 자연 보호 구역으로 구성되어 있습니다. 고대 그리스 전설에 따르면 (몬테 하초와 함께) 알려진 세계의 서쪽 경계를 표시했습니다.'),
			('TXT_KEY_CIV5_FEATURES_GEYSER_HELP',			'예측 가능한 지열 활동과 장관을 이루는 효과로 알려진 원뿔형 간헐천입니다. 수십 년 동안 1~2시간마다 분출해 왔습니다. 공원에서 가장 높거나 큰 간헐천은 아니지만 다른 열적 특징과 연결되어 있지 않다는 사실에 기인할 수 있는 신뢰성 때문에 관광객과 과학자들 사이에서 유명합니다.'),
			('TXT_KEY_CIV5_FEATURES_POTOSI_HELP',			'은광석으로 "만들어진" 것으로 대중적으로 인식되는 산으로 식민지 시대에 막대한 양의 은을 제공한 것으로 유명합니다. 산에서의 채굴 작업 결과 인근 도시는 신대륙에서 가장 큰 도시 중 하나가 되었으며 결국 산은 불모지로 변했습니다.'),
			('TXT_KEY_CIV5_FEATURES_MT_SINAI_HELP',			'3대 아브라함 계통 종교의 성서에 따르면 예언자 모세가 하나님으로부터 십계명을 받은 성서 속 시나이산이라고 주장되는 여러 장소 중 하나입니다. 그것이 속한 산맥의 더 높은 봉우리들로 사방이 둘러싸여 있습니다.'),
			('TXT_KEY_CIV5_FEATURES_MT_KAILASH_HELP',		'세 지점의 교차점에 위치한 산으로 4가지 다른 종교의 신성한 봉우리입니다. 그 때문에 전 세계 사람들에게 매우 일반적인 순례지입니다. 과거에 등반가들이 산을 조사했지만 성공적인 등반 기록은 없으며 현재는 종교적 중요성으로 인해 등반이 금지되어 있습니다.'),
			('TXT_KEY_CIV5_FEATURES_ULURU_HELP',			'대륙 중앙에서 솟아나 넓은 평원으로 둘러싸인 거대한 사암 단일체입니다. 형성 주변 지역에는 샘, 물웅덩이, 바위 동굴, 고대 그림이 풍부합니다. 이 큰 바위가 많은 원주민 부족에게 신성한 장소이자 매우 중요한 토착 유적지이기 때문에 그러한 그림을 찾을 수 있습니다.'),
			('TXT_KEY_CIV5_FEATURES_LAKE_VICTORIA_HELP',	'세계에서 가장 큰 열대 호수이자 표면적 기준으로 세계에서 두 번째로 큰 담수호입니다. 게다가 지구상에서 가장 긴 강을 유지하는 데 큰 역할을 합니다. 이 호수에는 많은 종류의 고유종 물고기가 서식하고 있지만 일부 침입종의 출현으로 많은 종이 멸종 위기에 처했습니다.'),
			('TXT_KEY_CIV5_FEATURES_SOLOMONS_MINES_HELP',	'솔로몬 왕이 막대한 양의 금을 축적한 신화 속 광산입니다. 그는 강력하고 현명하며 엄청나게 부유한 통치자로 알려졌습니다. 수 세기 동안 모험가들은 솔로몬의 부의 비밀을 찾으려고 노력했지만 성공하지 못했습니다.'),
			('TXT_KEY_CIV5_FEATURES_SALAR_HELP',			'시간이 지남에 따라 증발한 여러 선사 시대 호수의 변형으로 형성된 세계 최대의 소금 평원입니다. 소금의 훌륭한 공급원이자 리튬이 매우 풍부한 매장지입니다. 평탄함 덕분에 지구 관측 위성의 고도계를 보정하는 데 이상적이며 비가 온 후에는 세계에서 가장 큰 거울로 변합니다.'),
			('TXT_KEY_CIV5_FEATURES_CAUSEWAY_HELP',			'고대 화산 균열 분출의 결과인 수천 개의 서로 연결된 현무암 기둥 지역입니다. 대부분의 기둥은 육각형이지만 일부는 4, 5, 7 또는 8개의 면을 가지고 있습니다. 지질 신화의 한 형태인 전설에 따르면 이 기둥들은 거인이 지은 물속으로 사라지는 둑길의 잔해입니다.'),
			('TXT_KEY_CIV5_FEATURES_MT_EVEREST_HELP',		'해발 고도가 지구상에서 가장 높은 봉우리로 상당한 경험을 가진 사람들을 포함하여 많은 등반가를 끌어들입니다. 표준 경로는 기술적으로 어렵지 않지만 고산병, 날씨 및 바람 조건, 눈사태와 같은 위험을 수반합니다. 수백 명의 사람들이 사망하여 많은 시신이 눈 아래에 남겨져 수습할 수 없게 되었습니다.'),
			('TXT_KEY_CIV5_FEATURES_RETBA_HELP',			'특이한 분홍색 조류가 무성하게 자란 소금 호수로 좁은 사구 회랑으로만 바다와 분리되어 있습니다. 색상은 건기에 특히 잘 보입니다. 호수는 염도가 높은 것으로 알려져 있으며 사람들이 자유롭게 떠다닐 수 있을 만큼 부력이 있습니다.'),
			('TXT_KEY_CIV5_FEATURES_BERMUDA_HELP',			'20세기 중반으로 거슬러 올라가는 도시 전설에 따르면 수많은 비행기, 배, 사람들이 불가사의하게 사라진 느슨하게 정의된 신비한 지역입니다. 초자연적 현상부터 나침반 편차, 멕시코 만류, 메탄 하이드레이트와 같은 수많은 자연적 설명, 인간의 실수 및 폭풍우 날씨에 이르기까지 이러한 비극을 설명하는 많은 이론이 있습니다.'),
			('TXT_KEY_CIV5_FEATURES_LUMI_BAY_HELP',			'자극을 받으면 파란색으로 빛나는 특이한 식물성 플랑크톤 종이 서식하는 만입니다. 생물 발광은 수질 조건과 주변 맹그로브 숲이 만든 생태계, 석호의 현대적 개발 부재, 수온, 만의 깊이 등 여러 요인의 결과입니다.'),
			('TXT_KEY_CIV5_FEATURES_DALLOL_HELP',			'지구상에서 가장 높은 평균 기온을 기록한 원뿔 모양의 화산입니다. 특이한 색상과 광물 패턴, 열수 샘에서 흐르는 강산성 유체로 유명합니다. 이러한 극한의 물리화학적 특성이 공존하기 때문에 지구상에서 가장 살기 힘든 곳입니다.'),
			('TXT_KEY_CIV5_FEATURES_MT_PAEKTU_HELP',		'남북한 모두에게 신성한 산으로 약 100년마다 분화하는 활화산입니다. 쑹화강, 두만강, 압록강 세 강의 발원지인 천지를 만든 분화는 지난 수천 년 동안 지구상에서 가장 크고 강력한 분화 중 하나였습니다.'),
			('TXT_KEY_CIV5_FEATURES_EYE_OF_SAHARA_HELP',	'사막 한가운데 위치한 뚜렷한 원형 지질 구조입니다. 지하 마그마 관입이 위에 있는 퇴적암 층을 변형시켜 형성된 침식된 지질 돔입니다. 가장 오래된 층은 구조의 중앙에 노출되어 있습니다. 동심원 고리 모양으로 나타나며 공중이나 우주에서만 전체 형태를 볼 수 있습니다.'),
			('TXT_KEY_CIV5_FEATURES_BLUE_HOLE_HELP',		'해안에 가깝고 산호초와 산호섬으로 둘러싸인 큰 싱크홀입니다. 해수면이 훨씬 낮았던 여러 빙하기 단계 동안 형성되었습니다. 깊이 때문에 매우 인기 있는 다이빙 장소이자 주요 관광 명소입니다. 또한 자크 쿠스토의 가장 유명한 탐험을 포함하여 여러 해양 과학 탐험의 장소이기도 했습니다.'),
			('TXT_KEY_CIV5_FEATURES_GALAPAGOS_HELP',		'독특한 동식물이 있는 고립된 화산 군도입니다. 이 지역에 서식하는 거의 모든 조류, 포유류, 파충류와 대부분의 식물이 고유종인 것으로 추정됩니다. 생물학자 찰스 다윈은 갈라파고스 제도를 방문하여 그곳에서 발견된 동식물을 연구하고 목록화했으며, 그의 노트와 스케치는 "진화론"의 영감과 증거가 되었습니다.'),
			('TXT_KEY_CIV5_FEATURES_HA_LONG_HELP',			'수백만 년 전에 만들어진 다양한 모양과 크기의 수천 개의 석회암 카르스트와 섬이 있는 만입니다. 선사 시대 인류와 수많은 문화가 거주해 왔습니다. 사람들을 보호하고 나라를 지키기 위해 만으로 내려온 "하강하는 용"에 대한 전설이 있습니다.'),
			('TXT_KEY_CIV5_FEATURES_ZHANGJIAJIE_HELP',		'카르스트 지역에서는 드문 화학적 침식이 아닌 수년간의 물리적 침식의 결과인 기둥 모양의 형성물입니다. 그 아름다움은 공상 과학 영화 "아바타"의 판도라 행성의 독특한 배경에 영감을 주었습니다. 문자 그대로 "백룡 엘리베이터"인 백룡 엘리베이터로도 알려져 있으며 세계에서 가장 높은 실외 엘리베이터가 되었습니다.'),
			('TXT_KEY_CIV5_FEATURES_AURORA_HELP',			'코로나 구멍과 코로나 질량 방출에서 나오는 태양풍의 결과로 지구 자기권에 의해 생성되는 하늘의 아름다운 빛 효과입니다. 주로 극지방의 고위도에서 관찰할 수 있지만 때로는 저위도에서도 관찰할 수 있으며 빨간색과 녹색에서 파란색과 자외선에 이르기까지 다양한 색상의 표면, 호 또는 코로나와 같은 다양한 모양을 형성할 수 있습니다.'),
			('TXT_KEY_CIV5_FEATURES_ARCH_HELP',				'침식으로 노출된 섬세한 사암 형성물입니다. 아치는 가장 잘 알려진 랜드마크이며 주 번호판과 우표에 묘사되어 있습니다. 동계 올림픽 성화 봉송이 아치를 통과했으며 등반가들에게 도전 과제를 제시하기도 했지만 점진적인 악화로 인해 현재 등반이 금지되어 있습니다.'),
			('TXT_KEY_CIV5_FEATURES_DANXIA_HELP',			'수백만 년 전 사암과 기타 광물로 형성된 아름답고 다채로운 언덕과 산으로 다층 케이크를 닮았습니다. 바람, 비, 시간이 다양한 색상, 패턴, 크기의 탑, 기둥, 협곡을 포함한 놀라운 모양을 조각한 덕분에 전 세계의 과학자와 사진작가들에게 훌륭한 목표가 되었습니다.'),
			('TXT_KEY_CIV5_FEATURES_JEJU_DO_HELP',			'분출하는 마그마의 잔해인 응회암으로 구성된 거대한 화산 칼데라입니다. 처음에는 섬과 분리되어 있었지만 결국 합쳐졌으며 현재 한국 최고의 관광 명소 중 하나입니다. 주변이나 정상에서 가장 아름다운 일출을 포착할 수 있다고 하여 성산일출제가 열립니다.'),
			('TXT_KEY_CIV5_FEATURES_MARIANA_HELP',			'지구상에서 가장 깊은 해구로 에베레스트산 정상보다 해수면에서 2km 이상 더 깊으며 지각판의 섭입으로 형성되었습니다. 지구상에서 가장 오래된 귀중한 해양 지각이나 기록적인 깊이에 사는 유기체 때문이기도 하지만 다양한 테스트를 가능하게 하는 매우 높은 압력 때문에 많은 연구 임무의 일반적인 목표입니다.');